<script setup lang="ts">
import {computed,onMounted,onUnmounted,nextTick,ref,watch} from 'vue';
import {Bubble} from 'vue-element-plus-x';
import {ElInput,ElMessage,ElMessageBox} from 'element-plus';
import type {Snapshot,Thresholds} from '../../contracts/monitoring';
import type {Session,Message,ToolRecord} from '../../contracts/assistant';
import {assistant as a,activeSession,modelOptions,loadAssistant,newSession,sendQuestion,stopQuestion,assistantAction} from './assistant';
import AssistantMarkdown from './AssistantMarkdown.vue';
import AssistantSessions from './AssistantSessions.vue';
import AssistantToolDetail from './AssistantToolDetail.vue';
import {copyText as copyChatText} from './clipboard';
const props=defineProps<{snapshot?:Snapshot;thresholds:Thresholds;compact?:boolean}>();
const emit=defineEmits<{continue:[]}>();
const messages=ref<HTMLElement>(),messageContent=ref<HTMLElement>(),sender=ref<InstanceType<typeof ElInput>>();
const sidebar=ref(true),sessionDrawer=ref(false),mobile=ref(false),following=ref(true),unread=ref(false),detailsOpen=ref(false);
const selected=ref<{messageId:string;toolId?:string;index?:number}>();
const detailMessage=computed(()=>activeSession.value?.messages.find(m=>m.id===selected.value?.messageId)??(selected.value?.index!==undefined?activeSession.value?.messages[selected.value.index]:undefined));
const detailTool=computed(()=>detailMessage.value?.tools?.find(t=>t.id===selected.value?.toolId));
const time=(s:string)=>new Date(s).toLocaleString('zh-CN',{hour12:false,timeZone:'Asia/Shanghai'});
const toolNames:Record<string,string>={get_gpu:'查询 GPU',get_processes:'查询进程',get_users:'查询用户占用',get_storage:'查询存储',get_alerts:'查询告警'};
const statusNames={running:'调用中',complete:'已完成',error:'失败',stopped:'已停止'};
const generating=(m:Message)=>a.busy&&m.id===activeSession.value?.messages.at(-1)?.id&&m.role==='assistant';
function toolTitle(t:ToolRecord){const args=t.args as {gpuId?:number;user?:string;pid?:number;mount?:string}|undefined;return (toolNames[t.name]??t.name)+(args?.gpuId!==undefined?' · GPU '+args.gpuId:args?.pid?' · PID '+args.pid:args?.user?' · '+args.user:args?.mount?' · '+args.mount:'');}
function toolStatus(t:ToolRecord,m:Message){return t.status==='running'&&!generating(m)?'stopped':t.status;}
function selectSession(){sessionDrawer.value=false;detailsOpen.value=false;}
async function create(){try{await newSession();selectSession();await nextTick();sender.value?.focus();}catch(e){ElMessage.error((e as Error).message);}}
async function rename(session:Session){try{const {value}=await ElMessageBox.prompt('会话名称','重命名',{inputValue:session.title,inputValidator:v=>!!v.trim()&&v.length<=80,confirmButtonText:'保存',cancelButtonText:'取消'});await assistantAction('renameSession',{id:session.id,title:value});await loadAssistant();}catch(e){if(e instanceof Error)ElMessage.error(e.message);}}
async function remove(session:Session){try{await ElMessageBox.confirm('删除后无法恢复该会话。','删除会话',{confirmButtonText:'删除',cancelButtonText:'取消',type:'warning'});await assistantAction('deleteSession',{id:session.id});await loadAssistant();}catch(e){if(e instanceof Error)ElMessage.error(e.message);}}
async function send(){if(!props.snapshot||!a.loaded||a.busy||!a.input.trim())return;following.value=true;unread.value=false;await sendQuestion(props.snapshot,props.thresholds);await nextTick();sender.value?.focus();}
function inputKeydown(event:Event|KeyboardEvent){if(event instanceof KeyboardEvent&&event.key==='Enter'&&!event.shiftKey&&!event.isComposing){event.preventDefault();void send();}}
let lastScrollTop=0;
function scrollBottom(){if(messages.value){messages.value.scrollTop=messages.value.scrollHeight;lastScrollTop=messages.value.scrollTop;}unread.value=false;}
function latest(){following.value=true;scrollBottom();}
function onScroll(){if(!messages.value)return;const top=messages.value.scrollTop;const near=messages.value.scrollHeight-top-messages.value.clientHeight<72;if(near)following.value=true;else if(top<lastScrollTop)following.value=false;lastScrollTop=top;if(following.value)unread.value=false;}
let observer:ResizeObserver|undefined,query:MediaQueryList|undefined,frame=0;
function resized(){cancelAnimationFrame(frame);frame=requestAnimationFrame(()=>{if(following.value)scrollBottom();else unread.value=true;});}
function mediaChanged(){mobile.value=query?.matches??false;}
watch(()=>a.activeId,async()=>{following.value=true;unread.value=false;detailsOpen.value=false;await nextTick();scrollBottom();});
watch(()=>[activeSession.value?.messages.at(-1)?.text,activeSession.value?.messages.at(-1)?.tools?.map(t=>t.status).join(','),a.busy],async()=>{await nextTick();resized();},{flush:'post'});
async function copy(text:string){try{await copyChatText(text);ElMessage.success('已复制');}catch{ElMessage.info('无法自动复制，请选中文字复制');}}
function inspect(m:Message,tool?:ToolRecord){selected.value={messageId:m.id,toolId:tool?.id,index:activeSession.value?.messages.findIndex(row=>row.id===m.id)};detailsOpen.value=true;}
onMounted(async()=>{query=matchMedia('(max-width:760px)');mediaChanged();query.addEventListener('change',mediaChanged);observer=new ResizeObserver(resized);if(messageContent.value)observer.observe(messageContent.value);if(messages.value)observer.observe(messages.value);await loadAssistant();await nextTick();scrollBottom();});
onUnmounted(()=>{observer?.disconnect();query?.removeEventListener('change',mediaChanged);cancelAnimationFrame(frame);});
</script>
<template>
<div class="chat-workspace" :class="{'chat-compact':compact}">
 <aside v-if="!compact&&!mobile&&sidebar" class="chat-sidebar"><AssistantSessions @create="create" @select="selectSession" @rename="rename" @remove="remove"/></aside>
 <div class="chat-main">
  <header class="chat-top"><div class="chat-heading"><el-button v-if="!compact" text :aria-label="mobile?'打开会话列表':sidebar?'收起会话列表':'展开会话列表'" @click="mobile?sessionDrawer=true:sidebar=!sidebar">☰</el-button><div><strong>{{activeSession?.title??'新的对话'}}</strong><span>{{snapshot?.server??'等待服务器采样'}} · {{a.selection==='mock'?'规则模拟':a.engine==='pi'?'Pi Agent':'API 模型'}}</span></div></div><div class="chat-top-actions"><el-select v-model="a.selection" aria-label="选择模型" filterable :disabled="a.busy||a.loading"><el-option v-for="m in modelOptions" :key="m.value" :label="m.label" :value="m.value"/></el-select><el-button text @click="a.providerOpen=true">模型设置</el-button><el-button v-if="compact" text type="primary" @click="emit('continue')">继续对话</el-button></div></header>
  <el-alert v-if="a.error" :title="a.error" type="error" :closable="true" @close="a.error=''"/>
  <div class="chat-body"><div ref="messages" class="chat-scroll" @scroll.passive="onScroll"><div ref="messageContent" class="chat-content">
   <div v-if="!activeSession?.messages.length" class="chat-welcome"><div class="chat-welcome-symbol">SW</div><h2>一起看看服务器的运行情况</h2><p>查询资源、进程与存储，回答附带采样依据。</p><div class="chat-prompts"><button @click="a.input='哪个用户占用显存最多？'"><strong>用户与进程</strong><span>哪个用户占用显存最多？</span></button><button @click="a.input='查询 GPU4 的资源与进程情况。'"><strong>GPU 状态</strong><span>查看 GPU4 的资源与进程</span></button><button @click="a.input='查询各个挂载点的存储使用情况。'"><strong>存储空间</strong><span>查看磁盘用量与可用容量</span></button><button @click="a.input='分析当前资源状态，区分阈值风险与任务异常。'"><strong>资源分析</strong><span>检查当前阈值风险</span></button></div><el-button v-if="!a.loaded&&!a.loading" text @click="loadAssistant">重新加载</el-button></div>
   <article v-for="m in activeSession?.messages" :key="m.id" class="chat-turn" :class="m.role" :aria-label="m.role==='user'?'用户消息':'助手回答'">
    <Bubble :placement="m.role==='user'?'end':'start'" :variant="m.role==='user'?'filled':'borderless'" shape="round" :max-width="m.role==='user'?'82%':'100%'">
     <template v-if="m.role==='assistant'" #avatar><span class="chat-avatar">SW</span></template>
     <template #header><div class="chat-message-meta"><strong>{{m.role==='user'?'你':'Server Watch'}}</strong><span>{{time(m.at)}}</span></div></template>
     <template #content><div v-if="m.role==='user'" class="chat-user-text">{{m.text}}</div><div v-else class="chat-answer"><div v-if="m.tools?.length" class="chat-tool-cards"><button v-for="t in m.tools" :key="t.id" class="chat-tool-card" :class="toolStatus(t,m)" @click="inspect(m,t)"><span class="tool-dot"/><span>{{toolTitle(t)}}</span><small>{{statusNames[toolStatus(t,m)]}}</small><span class="tool-chevron">›</span></button></div><AssistantMarkdown v-if="m.text" :content="m.text" :final="!generating(m)"/><div v-else class="chat-waiting"><span v-if="generating(m)" class="chat-pulse"/>{{generating(m)?m.tools?.some(t=>t.status==='running')?'正在查询服务器数据…':'正在整理回答…':'未返回文本'}}</div><div v-if="generating(m)&&m.text" class="chat-stream-state"><span class="chat-pulse"/> 正在生成</div></div></template>
     <template v-if="m.role==='assistant'" #footer><div class="chat-answer-footer"><div class="chat-message-actions"><el-button text size="small" :disabled="!m.text" @click="copy(m.text)">复制回答</el-button><el-button text size="small" @click="inspect(m)">查看依据</el-button></div><span class="chat-sample">采样 {{time(m.capturedAt)}}<span v-if="m.snapshotId!==snapshot?.id"> · 历史采样</span></span><el-tag v-if="m.status==='stopped'||m.status==='error'" size="small" :type="m.status==='error'?'danger':'info'">{{m.status==='error'?'生成失败':'已停止'}}</el-tag></div></template>
    </Bubble>
   </article>
   <div v-if="a.busy&&activeSession?.messages.at(-1)?.role!=='assistant'" class="chat-waiting"><span class="chat-pulse"/> 正在连接模型…</div>
  </div></div><el-button v-if="!following" class="chat-latest" round size="small" @click="latest">{{unread?'有新内容 · ':''}}↓ 回到最新</el-button></div>
  <footer class="chat-compose"><div class="chat-compose-inner"><div class="chat-attachment-tags"><el-tag size="small" effect="plain" :type="snapshot?.source==='script'?'success':'info'">{{snapshot?.source==='script'?'真实采样':snapshot?'模拟采样':'等待采样'}}</el-tag><span>{{snapshot?time(snapshot.capturedAt)+' CST':'等待服务器数据'}}</span><span class="chat-context-hint">GPU · 用户进程 · 存储 · 阈值</span></div><div class="chat-input-shell"><el-input ref="sender" v-model="a.input" type="textarea" aria-label="监控问题" placeholder="输入监控问题，Enter 发送，Shift+Enter 换行" :maxlength="1000" :autosize="{minRows:2,maxRows:6}" :disabled="a.busy||!a.loaded||!snapshot" resize="none" @keydown="inputKeydown"/><div class="chat-input-actions"><el-button v-if="a.busy" class="chat-submit" @click="stopQuestion">停止生成</el-button><el-button v-else class="chat-submit" type="primary" :disabled="!a.input.trim()||!snapshot||!a.loaded" @click="send">发送 ↑</el-button></div></div><div class="chat-compose-note"><span>Enter 发送 · Shift+Enter 换行</span><span>{{a.input.length}} / 1000</span></div></div></footer>
 </div>
 <el-drawer v-model="sessionDrawer" title="会话列表" direction="ltr" size="280px" append-to-body><AssistantSessions @create="create" @select="selectSession" @rename="rename" @remove="remove"/></el-drawer>
 <el-drawer v-model="detailsOpen" :title="detailTool?'查询详情':'回答依据'" :size="mobile?'100%':'min(620px, 90vw)'" append-to-body><AssistantToolDetail v-if="detailTool" :tool="detailTool"/><div v-else-if="detailMessage" class="chat-evidence"><el-descriptions :column="1" border><el-descriptions-item label="模型">{{detailMessage.model}}</el-descriptions-item><el-descriptions-item label="采样时间">{{time(detailMessage.capturedAt)}}</el-descriptions-item><el-descriptions-item label="采样 ID">{{detailMessage.snapshotId}}</el-descriptions-item></el-descriptions><h3>查询记录</h3><button v-for="t in detailMessage.tools" :key="t.id" class="chat-tool-card" @click="selected={messageId:detailMessage.id,toolId:t.id}"><span>{{toolTitle(t)}}</span><small>{{statusNames[toolStatus(t,detailMessage)]}}</small><span>›</span></button><p v-if="!detailMessage.tools?.length" class="chat-detail-note">本次回答没有工具调用记录。</p><ul v-if="detailMessage.evidence?.length"><li v-for="e in detailMessage.evidence" :key="e">{{e}}</li></ul><p class="chat-detail-note">回答依据为本次采样与工具查询结果；用途推测仍需结合实际任务确认。</p></div></el-drawer>
</div>
</template>
<style scoped>
.chat-workspace{display:flex;height:calc(100dvh - 158px);min-height:480px;border:1px solid #dfe5ee;border-radius:12px;background:white;overflow:hidden;box-shadow:0 3px 14px #24395805}.chat-sidebar{width:224px;flex:none;background:#f7f9fc;border-right:1px solid #e4e9f0;padding:20px 14px}.chat-main{flex:1;min-width:0;min-height:0;display:flex;flex-direction:column}.chat-top{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:16px 22px;border-bottom:1px solid #eaf0f6;flex:none}.chat-heading{display:flex;gap:8px;align-items:center;min-width:0}.chat-heading>div{min-width:0}.chat-heading strong{display:block;white-space:nowrap;text-overflow:ellipsis;overflow:hidden;max-width:280px;font-size:14px}.chat-heading span{display:block;font-size:11px;color:#8793a3;margin-top:5px}.chat-top-actions{display:flex;gap:8px;align-items:center}.chat-top-actions .el-select{width:240px}.chat-main>.el-alert{margin:8px 16px;width:auto;flex:none}.chat-body{position:relative;flex:1;min-height:0}.chat-scroll{height:100%;overflow-y:auto;overflow-x:hidden;overscroll-behavior:contain;padding:28px 28px 18px;scrollbar-gutter:stable}.chat-content{max-width:900px;margin:auto;min-width:0}.chat-welcome{padding:40px 12px 28px;max-width:690px;margin:auto}.chat-welcome-symbol{display:flex;width:44px;height:44px;align-items:center;justify-content:center;border-radius:12px;background:#eaf1fb;color:#315d99;font-weight:700;margin-bottom:18px}.chat-welcome h2{font-size:23px;margin:0 0 10px;font-weight:650;color:#243952}.chat-welcome p{font-size:14px;color:#7a879a;margin:0 0 26px}.chat-prompts{display:grid;grid-template-columns:1fr 1fr;gap:12px}.chat-prompts button{font:inherit;text-align:left;padding:16px;border:1px solid #e2e8f1;border-radius:10px;background:#fbfcfe;cursor:pointer;transition:background .15s}.chat-prompts button:hover{background:#edf3fc;border-color:#bdcfe9}.chat-prompts strong,.chat-prompts span{display:block}.chat-prompts strong{font-size:13px;color:#405878;margin-bottom:8px}.chat-prompts span{font-size:12px;color:#8390a2}.chat-turn{margin-bottom:28px;min-width:0}.chat-avatar{display:flex;width:30px;height:30px;align-items:center;justify-content:center;background:#eaf0fa;border-radius:8px;color:#39649e;font-weight:650;font-size:10px}.chat-message-meta{display:flex;align-items:center;gap:12px;margin-bottom:8px;font-size:10px;color:#919baa}.chat-message-meta strong{font-size:12px;color:#62758d;font-weight:600}.chat-turn.user .chat-message-meta{justify-content:flex-end}.chat-user-text{font-size:14px;line-height:1.85;white-space:pre-wrap;overflow-wrap:anywhere}.chat-turn :deep(.elx-bubble__content-wrapper){min-width:0}.chat-turn.assistant :deep(.elx-bubble__content-wrapper){width:calc(100% - 42px)}.chat-turn.user :deep(.elx-bubble__content){background:#edf3fc;border-radius:12px;padding:12px 16px}.chat-turn.assistant :deep(.elx-bubble__content){padding:0;background:transparent;border:0;border-radius:0;box-shadow:none}.chat-answer{min-width:0;width:100%;overflow:hidden}.chat-tool-cards{display:flex;flex-wrap:wrap;gap:8px;margin:0 0 14px}.chat-tool-card{display:flex;align-items:center;gap:8px;background:#f8fafd;border:1px solid #e1e8f1;border-radius:8px;padding:8px 10px;font:inherit;font-size:12px;color:#506982;cursor:pointer;max-width:100%;text-align:left}.chat-tool-card:hover{border-color:#aec4e1;background:#f0f5fc}.chat-tool-card>span:nth-child(2){overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.chat-tool-card small{font-size:10px;color:#8290a2;white-space:nowrap}.tool-dot{width:6px;height:6px;border-radius:50%;background:#678a78;flex:none}.chat-tool-card.running .tool-dot{background:#4b7eb5;animation:pulse 1.3s infinite}.chat-tool-card.error .tool-dot{background:#bd5b58}.chat-tool-card.stopped .tool-dot{background:#a1aab6}.tool-chevron{color:#97a7ba;margin-left:auto}.chat-waiting,.chat-stream-state{display:flex;align-items:center;gap:8px;color:#8794a5;font-size:12px;min-height:30px}.chat-stream-state{margin-top:12px}.chat-pulse{width:6px;height:6px;border-radius:50%;background:#6080a9;animation:pulse 1.3s infinite}.chat-answer-footer{display:flex;align-items:center;flex-wrap:wrap;gap:8px 14px;margin-top:12px}.chat-message-actions{display:flex;gap:0}.chat-message-actions .el-button{padding:4px 6px;font-size:11px;color:#7588a0}.chat-sample{font-size:10px;color:#95a0af}.chat-latest{position:absolute;bottom:16px;left:50%;transform:translateX(-50%);box-shadow:0 3px 12px #263b5120;background:#fff;z-index:2}.chat-compose{border-top:1px solid #edf1f7;padding:12px 28px 14px;flex:none;background:#fff}.chat-compose-inner{max-width:900px;margin:auto}.chat-attachment-tags{display:flex;align-items:center;gap:9px;flex-wrap:wrap;margin-bottom:10px;font-size:10px;color:#8a97a8}.chat-context-hint{margin-left:auto}.chat-input-shell{border-radius:12px;border-color:#dbe3ee;box-shadow:0 2px 8px #253c5610}.chat-input-shell{border:1px solid #dbe3ee;overflow:hidden}.chat-input-shell :deep(.el-textarea__inner){box-shadow:none!important;font-size:14px;line-height:1.8;padding:12px 14px;background:transparent}.chat-input-actions{display:flex;justify-content:flex-end;padding:0 10px 10px}.chat-compose-note{display:flex;justify-content:space-between;font-size:10px;color:#9aa5b4;margin-top:8px}.chat-submit{border-radius:7px}.chat-evidence{display:flex;flex-direction:column;gap:12px}.chat-evidence h3{font-size:14px;margin:8px 0}.chat-evidence li{font-size:13px;line-height:1.8;overflow-wrap:anywhere}.chat-detail-note{color:#8793a4;font-size:12px;line-height:1.8}.chat-compact{height:calc(100dvh - 118px);min-height:400px;border:0;border-radius:0;box-shadow:none}.chat-compact .chat-top{padding:12px 0;flex-wrap:wrap}.chat-compact .chat-top-actions .el-select{width:180px}.chat-compact .chat-scroll{padding:22px 0}.chat-compact .chat-compose{padding:12px 0}.chat-compact .chat-heading strong{max-width:220px}.chat-compact .chat-welcome{padding:24px 0}.chat-compact .chat-context-hint{display:none}
@keyframes pulse{50%{opacity:.35}}@media(prefers-reduced-motion:reduce){.chat-pulse,.tool-dot{animation:none!important}}@media(max-width:1100px){.chat-top{flex-wrap:wrap;padding:14px 18px}.chat-top-actions{width:100%}.chat-top-actions .el-select{flex:1}.chat-scroll{padding:22px 20px}.chat-compose{padding:12px 20px}}@media(max-width:760px){.chat-workspace{height:calc(100dvh - 150px);min-height:480px;border-radius:9px}.chat-top{padding:12px}.chat-heading strong{max-width:240px}.chat-top-actions .el-select{width:150px}.chat-scroll{padding:20px 12px}.chat-compose{padding:10px 12px}.chat-context-hint{display:none}.chat-welcome{padding:24px 0}.chat-welcome h2{font-size:20px}.chat-prompts{gap:9px}.chat-prompts button{padding:12px}.chat-turn.assistant :deep(.elx-bubble__content-wrapper){width:calc(100% - 36px)}.chat-avatar{width:25px;height:25px}.chat-sample{width:100%}.chat-compact{height:calc(100dvh - 116px)}.chat-message-meta span{font-size:9px}}
</style>
